figma.skipInvisibleInstanceChildren=false;
const pack=ids=>{let prev='',body='';for(const id of [...ids].sort()){let i=0;while(i<prev.length&&i<id.length&&prev[i]===id[i])i++;body+=i+'\t'+id.slice(i)+'\n';prev=id;}const dict=new Map();for(let i=0;i<256;i++)dict.set(String.fromCharCode(i),i);let next=256,w='',codes=[];for(const ch of body){const wc=w+ch;if(dict.has(wc))w=wc;else{codes.push(dict.get(w));if(next>=65535)throw Error('ID encoder capacity');dict.set(wc,next++);w=ch;}}if(w)codes.push(dict.get(w));const bytes=codes.flatMap(n=>[n>>8,n&255]),chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';let out='';for(let i=0;i<bytes.length;i+=3){const a=bytes[i],b=bytes[i+1],c=bytes[i+2],n=(a<<16)|((b||0)<<8)|(c||0);out+=chars[(n>>18)&63]+chars[(n>>12)&63]+(b===undefined?'=':chars[(n>>6)&63])+(c===undefined?'=':chars[n&63]);}return out;};
const cloneRoots=async entries=>{const created=[],mutated=[],proof=[];for(const [id,targetMode,stageIndex,withinStage]of entries){const source=await figma.getNodeByIdAsync(id);if(!source||source.parent.id!=='3:5')throw Error('Missing source '+id);const name=source.name.replace(/\s+\b(?:Light|Dark)\b/g,'')+' '+(targetMode==='17:2'?'Dark':'Light')+' / INT-04 exact '+id;if(figma.currentPage.children.some(n=>n.name===name))throw Error('Already staged '+id);const originals=[source,...source.findAll(()=>true)];const fonts=new Map();for(const t of originals.filter(n=>n.type==='TEXT'))for(const seg of t.getStyledTextSegments(['fontName']))fonts.set(JSON.stringify(seg.fontName),seg.fontName);await Promise.all([...fonts.values()].map(f=>figma.loadFontAsync(f)));const clone=source.clone();clone.name=name;clone.x=63800+(withinStage%8)*1640;clone.y=stageIndex*10000+Math.floor(withinStage/8)*1080;clone.setExplicitVariableModeForCollection('VariableCollectionId:17:3',targetMode);const copies=[clone,...clone.findAll(()=>true)];if(copies.length!==originals.length)throw Error('Clone shape changed '+id);const typeCounts={};const families=new Set();const imageNodes=[];let textCount=0;for(let i=0;i<copies.length;i++){const a=originals[i],b=copies[i];created.push(b.id);typeCounts[b.type]=(typeCounts[b.type]||0)+1;if(a.type!==b.type||a.width!==b.width||a.height!==b.height)throw Error('Clone geometry changed '+id+' '+i);if(JSON.stringify(a.boundVariables)!==JSON.stringify(b.boundVariables))throw Error('Clone binding changed '+id+' '+i);if(b.type==='TEXT'){textCount++;if(a.characters!==b.characters||JSON.stringify(a.getStyledTextSegments(['fontName','textStyleId']))!==JSON.stringify(b.getStyledTextSegments(['fontName','textStyleId'])))throw Error('Clone text changed '+id+' '+i);for(const s of b.getStyledTextSegments(['fontName']))families.add(s.fontName.family);}if(b.type==='INSTANCE'&&JSON.stringify(a.componentProperties)!==JSON.stringify(b.componentProperties))throw Error('Clone variant changed '+id+' '+i);if(Array.isArray(b.fills)&&b.fills.some(f=>f.type==='IMAGE'))imageNodes.push([b.id,b.name,b.width,b.height]);if(b!==clone&&b.explicitVariableModes?.['VariableCollectionId:17:3']){b.setExplicitVariableModeForCollection('VariableCollectionId:17:3',targetMode);mutated.push(b.id);}}if([...families].some(x=>x!=='Inter'))throw Error('Product font changed '+id);const clean=root=>root.reactions.map(r=>({trigger:r.trigger,actions:JSON.parse(JSON.stringify(r.actions||(r.action?[r.action]:[])))})).filter(r=>!(r.trigger?.type==='AFTER_TIMEOUT'&&Math.abs(r.trigger.timeout-0.001)<0.0000001));await clone.setReactionsAsync(clean(clone));mutated.push(clone.id);proof.push({sourceId:id,cloneId:clone.id,name,theme:targetMode,sourceTheme:source.explicitVariableModes['VariableCollectionId:17:3'],nodes:copies.length,textCount,typeCounts,fontFamilies:[...families],imageNodes,bounds:[clone.x,clone.y,clone.width,clone.height],exactTextAndStyles:true,exactBindings:true,exactInstanceProperties:true,staged:true});}return {createdRootIds:proof.map(x=>x.cloneId),createdNodeIdsEncoding:'sorted-frontcode-prefixlength-tab-suffix-newline/LZW16-BE/base64',createdNodeIdsLzw16Base64:pack(created),createdNodeCount:created.length,mutatedNodeIds:mutated,rows:proof};};
